ALTER DATABASE [{db}] ADD FILEGROUP MOD CONTAINS MEMORY_OPTIMIZED_DATA
GO
ALTER DATABASE [{db}] ADD FILE (NAME = '{db}_mod', FILENAME = '/var/opt/mssql/data/{db}_mod') TO FILEGROUP MOD
GO
CREATE TABLE dbo.Hot (Id int NOT NULL CONSTRAINT PK_Hot PRIMARY KEY NONCLUSTERED, Name nvarchar(50) NOT NULL) WITH (MEMORY_OPTIMIZED = ON)
GO
CREATE PROCEDURE dbo.GetHot @Id int WITH NATIVE_COMPILATION, SCHEMABINDING AS BEGIN ATOMIC WITH (TRANSACTION ISOLATION LEVEL = SNAPSHOT, LANGUAGE = N'us_english') SELECT Name FROM dbo.Hot WHERE Id = @Id END
